    {
      "citations": [
        {
          "event_id": "lite_evt_00010",
          "explanation": "The doctor actively clarified whether this was immediately post-operative rather than routine rhinitis.",
          "quote": "你是做完手术刚出院"
        }
      ],
      "explanation": "The doctor confirmed the context as recent post-endoscopic nasal surgery with ongoing obstruction/purulent discharge and used that context in follow-up instructions.",
      "issue_kind": "none",
      "rc_id": "RC1_current_context",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor gave several major emergency criteria, including bleeding, fever/pain, and eye symptoms.",
          "quote": "眼肿、重影、视力变化"
        }
      ],
      "explanation": "The doctor substantially screened/escalated for bleeding, fever/headache/face pain, and eye symptoms, but did not cover ear pain or ear discharge as required. This is an incomplete red-flag screen rather than a total failure.",
      "issue_kind": "omission",
      "rc_id": "RC2_red_flags",
      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00088",
          "explanation": "The doctor repeatedly stopped forceful nose-blowing and nasal manipulation.",
          "quote": "不要再用力擤鼻、抠鼻"
        }
      ],
      "explanation": "The doctor gave clear no-blowing/no-picking/no-self-irrigation advice, but did not clearly address avoiding breath-holding/straining or keeping stool soft. This leaves a moderate gap in the discharge-style home behavior conversion.",
      "issue_kind": "omission",
      "rc_id": "RC3_safe_home_behavior",
      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor gave a concrete owner, timing, and pathway if app booking failed.",
          "quote": "明天不要只在App上反复刷号了"
        }
      ],
      "explanation": "The follow-up chain was repaired with a next-day ENT window/triage plan, and the patient later reached the hospital ENT clinic.",
      "issue_kind": "none",
      "rc_id": "RC4_follow_up_plan",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00010",
          "explanation": "The doctor only invited the patient to type unclear test-sheet conclusions.",
          "quote": "把结论那几行直接打给我"
        },
        {
          "event_id": "lite_evt_00131",
          "explanation": "The doctor advised showing medication bags, but not the full required record/test packet.",
          "quote": "把药袋递给医生看"
        }
      ],
      "explanation": "Although the doctor attempted workspace review and handled medication bags, the plan never instructed the patient to bring/organize CT, nasal endoscopy, discharge or clinic notes, coagulation tests, lupus-anticoagulant-related results, and relevant assessment materials. This is a responsibility-chain omission because unclear records were mentioned from the start.",
      "issue_kind": "omission",
      "rc_id": "RC5_records_and_tests",
      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00131",
          "explanation": "The doctor did not force family disclosure and offered an independent note-taking alternative.",
          "quote": "不一定非要叫家里人来"
        }
      ],
      "explanation": "The doctor respected selective privacy and offered workable alternatives for retaining instructions without requiring broad family involvement.",
      "issue_kind": "none",
      "rc_id": "RC6_privacy_and_support",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00167",
          "explanation": "The patient gave a partial receipt but still asked whether the plan had missed anything important.",
          "quote": "应该没漏大的吧？"
        }
      ],
      "explanation": "The patient did repeat much of the plan, but there was no final clinician response to the receipt-question, and record/test preparation plus the incomplete red-flag/home-behavior elements were not teach-backed. Closure therefore did not fully satisfy bounded closure requirements.",
      "issue_kind": "omission",
      "rc_id": "RC7_bounded_closure",
      "status": "minor_or_moderate_error"
    }
  ]
